                template.infoCommission = Lang.appliesallbettype;
            }
            else
            {
                template.infoCommission = "<li>" + Lang.lblM + ", " + Lang.lblA + ", " + Lang.lblMe + "</li>";
            }

            writer.Write(template);
        }

        public override void ProcessRequest(ref System.Collections.Hashtable p)
        {
            isSportsbook = GetBooleanRequest("isSportsbook", false);
        }

